"""Offline regression report by default. --live explicitly opts into model calls."""
import argparse
import asyncio
from datetime import datetime, timezone
from hashlib import sha256
import html
import json
from pathlib import Path
import time
from app.schemas.chat import ChatRequest
from app.services import answers, prompts
from app.services.knowledge import ARTICLES, search

HERE = Path(__file__).parent
LIMITS = [
    'Offline checks pass sample strings directly to validators; they are not answers generated by a live model.',
    'Matching source IDs and figures does not prove semantic accuracy, currency or correct attribution.',
    'Written-out numbers, translations and complex multi-part answers still need human review.',
    'Live two-customer isolation and live complex-question model reliability remain deferred.',
]

async def evaluate(live=False):
    dataset = HERE / ('cases.json' if live else 'offline_cases.json')
    cases = json.loads(dataset.read_text())
    results = []
    for case in cases:
        started = time.monotonic()
        request = ChatRequest(messages=case.get('history', []) + [{'role':'user', 'content':case['question']}], language=case.get('language', 'English'))
        row = {'id':case['id'], 'question':case['question']}
        try:
            if live:
                response = await answers.make_answer(request)
                row.update(status='needs_human_review', review_check=case['check'], **response)
            else:
                if case['expect']=='fixed':
                    response = await answers.make_answer(request,allow_model=False)
                    rejected = False
                else:
                    articles = answers.retrieve(case['question'], request.messages, request.language)
                    evidence = [{'id':a.id,'text':a.content} for a in articles]
                    raw = json.dumps({'answer':case['answer'],'source_ids':case['source_ids']})
                    answer,ids,reason = answers.check_answer(raw,evidence)
                    rejected = reason is not None
                    response = {'answer':case['answer'],'source_ids':case['source_ids'],
                                'validation_reason':reason,'sample_only':True}
                checks = {'expected_response': (rejected if case['expect']=='rejected' else not rejected)}
                if case.get('contains'):
                    checks['required_guidance'] = case['contains'] in response['answer']
                if case.get('required_source'):
                    checks['source_retrieved'] = case['required_source'] in [a.id for a in search(case['question'])]
                if case['expect']=='accepted':
                    checks['sample_validated'] = response['answer'] == case['answer']
                row.update(status='pass' if all(checks.values()) else 'fail', checks=checks, **response)
        except Exception as exc:
            # Never persist exception messages, which may contain provider details.
            row.update(status='error', error_type=type(exc).__name__)
        row['seconds'] = round(time.monotonic() - started, 3)
        results.append(row)
    knowledge = json.dumps([vars(a) for a in ARTICLES], sort_keys=True)
    services = Path(answers.__file__).parent
    implementation = b''.join((services / name).read_bytes() for name in
        ('answers.py', 'knowledge.py', 'source_checks.py', 'llm.py') if (services / name).exists())
    return {
        'mode':'live_manual_review' if live else 'offline_validator_checks',
        'created_at':datetime.now(timezone.utc).isoformat(),
        'dataset_sha256':sha256(dataset.read_bytes()).hexdigest(),
        'knowledge_sha256':sha256(knowledge.encode()).hexdigest(),
        'prompt_version':prompts.current()['id'],
        'implementation_sha256':sha256(implementation).hexdigest(),
        'summary':{status:sum(r['status']==status for r in results) for status in ('pass','fail','error','needs_human_review')},
        'limits':LIMITS, 'results':results,
    }

def write_report(report, output):
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n')
    esc = lambda value: html.escape(str(value))
    rows = ''.join(f"<tr><td>{esc(r['id'])}</td><td>{esc(r['status'])}</td><td>{esc(r['question'])}</td><td>{esc(r.get('answer',r.get('error_type','')))}</td></tr>" for r in report['results'])
    comparison = ''
    if 'comparison' in report:
        comparison = '<h2>Before and after</h2><pre>' + esc(json.dumps(report['comparison'], indent=2)) + '</pre>'
    output.with_suffix('.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Banking evaluation results</title><style>body{font:16px system-ui;max-width:1100px;margin:32px auto;padding:0 20px;color:#162b3a}table{border-collapse:collapse;width:100%}td,th{border:1px solid #cbd5df;padding:12px;text-align:left;vertical-align:top;overflow-wrap:anywhere}pre{white-space:pre-wrap}h1,h2{color:#124f68}</style><h1>Banking evaluation results</h1>'''
        + '<p>Mode: ' + esc(report['mode']) + '</p><p>Generated: ' + esc(report['created_at']) + '</p>'
        + '<p>' + esc(report['summary']) + '</p><ul>' + ''.join('<li>'+esc(x)+'</li>' for x in report['limits']) + '</ul>'
        + comparison + '<h2>Individual results</h2><table><thead><tr><th>Case</th><th>Result</th><th>Question</th><th>Response</th></tr></thead><tbody>' + rows + '</tbody></table></html>')

async def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--live', action='store_true', help='Use configured model; responses require human review')
    parser.add_argument('--output', default='evaluation-results.json')
    parser.add_argument('--compare', type=Path, help='Previous report using the same dataset and mode')
    args = parser.parse_args()
    previous = json.loads(args.compare.read_text()) if args.compare else None
    # Validate comparison before any opt-in live calls.
    dataset = HERE / ('cases.json' if args.live else 'offline_cases.json')
    mode = 'live_manual_review' if args.live else 'offline_validator_checks'
    if previous and (previous['dataset_sha256'] != sha256(dataset.read_bytes()).hexdigest() or previous['mode'] != mode):
        parser.error('Comparison requires the same dataset and mode')
    report = await evaluate(args.live)
    if previous:
        old = {r['id']:r['status'] for r in previous['results']}
        report['comparison'] = {'before':previous['summary'], 'after':report['summary'],
            'changed_cases':[{'id':r['id'], 'before':old.get(r['id']), 'after':r['status']} for r in report['results'] if old.get(r['id']) != r['status']]}
    write_report(report, args.output)
    print(json.dumps({'mode':report['mode'], **report['summary']}))
    return 1 if report['summary']['fail'] or report['summary']['error'] else 0

if __name__ == '__main__':
    raise SystemExit(asyncio.run(main()))
